"""Seal N1R preparation, actual metrics and test limitations; never run readers."""
from greekocr.ops.data_root import input_path as _data_input
import json
from pathlib import Path
import sys
import xml.etree.ElementTree as ET
from collections import Counter
ROOT=Path(__file__).resolve().parents[2]
sys.path[:0]=[str(ROOT),str(Path(__file__).parent)]
from greekocr.numerics.ink_rule import load_rule,sha,CLASSES,decide,measurements,metrics
from greekocr.numerics.combine_v2 import MEANINGS
from n1t_packs import rows
from n1_pack_closure import scan
from n1r_fit import write
BASE=ROOT/'artifacts/n1'


def test_result(path):
    xml=ET.parse(path)
    cases=xml.findall('.//testcase')
    return dict(path=str(path),sha256=sha(path),passed=sum(not c.findall('failure') and not c.findall('error') and not c.findall('skipped') for c in cases),
                failed=[c.attrib['classname']+'::'+c.attrib['name'] for c in cases if c.findall('failure') or c.findall('error')],
                per_file=dict(Counter(c.attrib['classname'] for c in cases if not c.findall('failure') and not c.findall('error'))))


def main():
    rule=load_rule(BASE/'n1r/rule.json');held=json.loads((BASE/'n1r/held_metrics.json').read_text());build=json.loads((BASE/'n1e/build.json').read_text())
    targeted=test_result(BASE/'N1R_TESTS.xml');regression=test_result(BASE/'N1R_REGRESSION.xml')
    assert not targeted['failed']
    fixtures=targeted['per_file']['tests.test_n1r_gate_apply']
    closures=[]
    for c in build['dry_runs']:
        rd=Path(build['pack_root'])/c['context']/c['reader']
        r=scan(rd,BASE/'n1e',completed=True,meanings=MEANINGS)
        if not r['ok']:raise ValueError('new locked pack closure changed: '+str(r['violations']))
        if (rd/'answers.jsonl').exists():raise ValueError('unexpected locked answers')
        closures.append(dict(context=c['context'],reader=c['reader'],manifest_sha256=r['manifest_sha256']))
    cfg=rule['config'];truth=rows(_data_input(BASE/'n1r/truth.jsonl'));train=[s for s in truth if s['split']=='fit']
    fit_stats=metrics([s['truth'] for s in train],[decide(s,rule) for s in train])
    measurable=Counter(s['split'] for s in truth if s['truth']=='raised dot' and measurements(s)['candidate_count']==1 and not measurements(s)['hyphen_length_stroke'])
    matrix=held['confusion_matrix']
    abbreviations=['raised','baseline','comma','hyphen','en','em','space','nothing','unsure']
    table=['| Truth → prediction | '+' | '.join(abbreviations)+' |','|---|'+'---:|'*len(CLASSES)]
    for t in (*CLASSES,'any dash'):
        if sum(matrix[t].values()):table.append('| '+t+' | '+' | '.join(str(matrix[t][p]) for p in CLASSES)+' |')
    report=ROOT/'docs/records/labelfix/secondary/N1R_REPORT.md'
    text=f'''# N1-R — frozen preparation; release NOT qualified

Rule SHA256: `{rule['rule_hash']}`. **The held-out ≥99% precision gate is not established:** there are zero raised predictions, so precision is undefined (n=0), and recall is 0/2. No training labels, LQB entries or reader runs were produced. The locked scorer has not been run against real truth.

The seeded document split (`{cfg['seed']}`) uses source:item identity, including approved control documents: {held['fit_rows']} fit slots in {held['fit_documents']} documents, {held['rows']} held-out slots in {held['held_documents']} documents. The one-document difference is rounding of 111 documents. Every input development/control line passed `greekocr.numerics.locks.assert_fit_rows`; selected documents were also checked against `reserved_docs`. All eligible two/three-read agreements and resolved lead rulings are included. The sealed TS3 combined decisions are SHA-checked against the TS3 receipt. Holds, unresolved/VOID-only evidence and the mirrored/show-through line remain excluded; geometry-inferred “nothing” is not human truth. The four C1 raised controls are explicitly `c1_control_only`, so they remain pack controls and never enter fitting or held-out scoring, following their recorded “N1 never fits on” restriction. The approved typed controls contribute 78 eligible slots; two “any dash” controls retain that truth rather than acquiring an invented type.

There are 18 resolved raised truths: 16 fit and two held-out. Only {measurable.get('fit',0)} fit and {measurable.get('held',0)} held-out raised truths have a single measurable small component after the fixed screen. Overlapping Google digit boxes often leave no target component. This is a localization/measurement limitation; zero false positives with zero held-out positive predictions is not precision evidence. Fit raised precision is {fit_stats['raised_precision']} with {fit_stats['raised_predicted']} predictions; this is training evidence only. The held-out unsure rate is {held['unsure_rate']:.4%}.

## Rule and edit policy

`greekocr/numerics/ink_rule.py` consumes the existing renderer side record, generated by `greekocr.glyphs.components.line_glyphs` and the exact flanking digit top/baseline estimates. Every decision retains component count, full component/union boxes, normalized height/centre/width, token median digit width, gap width, helper x-height band, class, margin, reason and rule hash. Small crossing components remain visible; full-height digit components cannot become dot candidates. A component at least three native pixels wide and at least twice as wide as high is a hard horizontal-stroke veto, including crossing components. Multiple eligible components abstain. An empty nonpositive gap abstains because overlapping boxes cannot prove absent ink.

The fixed screens were specified in code before fitting. Raised boxes search four paddings around fit positives and four margin thresholds, prioritizing nonempty zero-false-positive fit predictions, then precision and recall. Other band/width cuts maximize fit accuracy over observed midpoint thresholds. The frozen numerical thresholds are:

```json
{json.dumps(dict(thresholds=cfg['thresholds'],edit_margin_min=cfg['edit_margin_min']),indent=2)}
```

The SHA is over the exact `artifacts/n1/n1r/rule.json` bytes; `rule.sha256` is the detached digest. The frozen JSON binds the classifier source SHA and truth-input hashes. Held-out truth was scored only after freezing, with no subsequent threshold changes. Locked measurement enumeration followed that freeze. Per-slot held decisions and complete truth/split records are in `artifacts/n1/n1r/`.

Only a Google `-` or `.` immediately between ASCII digits may become U+00B7, when the frozen raised class and margin pass. No grammar restriction is added to the release brief. All dashes are tag-only; an unsure decision retains the parent label and writes an unsure tag. A stroke veto always prevents an edit.

## Held-out confusion matrix

{chr(10).join(table)}

Raised precision: undefined, 0 predictions. Raised recall: 0/2 = 0. Hyphen/en/em/any-dash → raised: 0; baseline-dot → raised: 0. Precision uses **all** non-raised classes as possible errors, a stricter denominator than only baseline/hyphen negatives.

## Locked packs (prepared, no reads)

All 258 alternate locked lines have all numeric gaps and token boundaries enumerated: {build['slots']} slots. The read set is {build['selected_slots']} distinct slots: 372 Google inner `-`/`.` gaps, 334 additional frozen raised/dash predictions, and a seeded ceil(10%) = 68 of 678 remaining marked gaps (`{build['seed']}`). Rule classes are selection evidence only, never locked truth. All selected slots appear once per reader, r2 in reverse order with fresh IDs and deranged option letters. Each context has nine distinct approved controls, including raised, hyphen, en and em examples.

Pack root: `{build['pack_root']}/`. No reader pack lives in the repo; the shared builder rejects repo descendants and symlink aliases. The builder requires a frozen rule hash and an explicitly reserved evaluation population before accepting locked rows. Private keys and side records are under `artifacts/n1/n1e/`. The sep2 prompt is unchanged. Root `n1e` is wired through the launcher and mapper. All {len(closures)} sealed pack closures and launcher dry-runs passed; no probes or reads were invoked.

**Localization limit:** 193 enumerated slots have invalid geometry; 36 of those belong to the required read set (33 digit-box-outside-crop, three reversed-box cases). Their images preserve the whole line without an invented target marker. These 36 are unresolved for scoring unless the lead supplies a slot-specific ruling; reader agreement on an unlocalized whole line cannot establish target truth. The current packs therefore need this adjudication/localization work before their truth can close the gate. Two locked rows have changed parent labels; their original Google text drives enumeration, and both values are retained in `lines.jsonl`.

Ten contexts × two readers contain {build['reads_including_controls']} reads, including 180 control reads. At 0.2 points per 100 reads: **{build['points']:.3f} points** (targets alone: {build['selected_slots']*2*.2/100:.3f}). This is a read-count estimate, not observed consumption.

## Scorer and training applier (fixtures only)

`scripts/numerics/n1_gate.py` replays the frozen decisions, validates sealed preparation/public packs, canonical scans, VALID control gates and original-answer custody, then accepts two independent high-confidence agreements or explicit lead rulings. It does not require rule agreement to admit dash truth. Disagreements, holds and unlocalized targets without lead rulings cannot pass. Passing requires ≥99% raised precision with nonzero raised predictions/truth, zero edits on all true hyphen/en/em/any-dash ranges, and complete adjudication. Recall and both selected/all-enumerated unsure rates are reported; sampled read-set recall is explicitly not full-population recall.

Future explicit scoring command (not run):

```sh
python scripts/numerics/n1_gate.py --lead artifacts/n1/n1e/lead_e.jsonl
```

`scripts/numerics/n1_apply_train.py` recomputes the real locked gate rather than trusting a saved passed flag, also requires qualified held-out dev precision, then enumerates every numeric token/boundary of every collection-v2 training row. Crop-bound DocAI digit symbols or a `--geometry` sidecar supply exact localization; absent localization produces per-slot unsure records and no edit. A geometry sidecar is JSONL with `line_id`, `crop_sha256`, `parent_label_sha256` (SHA256 of UTF-8 label), and line-complete `slots` carrying exact `slot_id/start/end/glyph/geometry/digit_widths`; the applier recomputes pixel measurements rather than accepting supplied classes or measurements. Default v2 rows do not contain DocAI symbol geometry, so useful edits require that localized sidecar. Missing or mismatched crops fail closed. No uniform text-to-pixel guess or new reader is introduced.

After the gates pass, the applier writes the complete parent-ID stream `n1_v1_train.jsonl` with parent/new labels, edits, tags, decision-record references and rule hash; the complete `n1_v1_train_decisions.jsonl`; a SHA-bound manifest; and an atomic LQB registry update preserving existing entries. None of those production outputs or the `n1_v1_train` registry entry has been created in this task. The unchanged input is `~/Projects/greek-ocr-toolkit/docs/harvest/collection/v2/import_real_v2_train.jsonl`.

## Validation and remaining work

New targeted tests: **{targeted['passed']} passed**, including **{fixtures} scorer/applier fixture tests**. Fixtures cover the exact 99% precision boundary, range false edits, no-prediction refusal, unusable votes, lead authority, localization holds, real-pixel dot edits and stroke tags, complete per-slot records, crop/offset custody, gated output refusal, manifest and LQB registration. Full N1 regression run: **{regression['passed']} passed, {len(regression['failed'])} failed**. The six failures reference missing images in historical `n1`, `n1t2`, and `n1t3` scratch packs; new `n1e` closures pass. Historical packs were not rewritten to hide those failures. Exact failures and traces are retained in `N1R_REGRESSION.xml`.

Next work is qualification: establish usable held-out raised evidence/localization without tuning this frozen rule on held/locked truth, resolve the 36 unlocalized locked targets, obtain the two actual reads and lead rulings, then run the locked scorer. This frozen candidate cannot be used to publish training edits while its dev precision remains unqualified. Network, browser/computer use, reader launches and `.git` writes were not used.
'''
    report.write_text(text)
    sources=[ROOT/p for p in (
        'greekocr/numerics/ink_rule.py','greekocr/numerics/line_complete.py','greekocr/numerics/locks.py',
        'greekocr/numerics/slots_geom.py','greekocr/numerics/tokens.py','greekocr/numerics/dash.py','greekocr/numerics/prune.py',
        'greekocr/numerics/combine_v2.py','greekocr/glyphs/components.py',
        'scripts/numerics/n1r_fit.py','scripts/numerics/n1e_prepare.py','scripts/numerics/n1_gate.py',
        'scripts/numerics/n1_apply_train.py','scripts/numerics/n1r_receipt.py','scripts/numerics/n1_render.py',
        'scripts/numerics/n1t_packs.py','scripts/numerics/n1_pack_closure.py','scripts/numerics/n1t_combine.py',
        'scripts/numerics/n1_map_answers.py','scripts/secondary/reading/n1_launch.py',
        'scripts/secondary/reading/scan_packs.py','scripts/secondary/reading/scan_rollout.py',
        'tests/test_n1r.py','tests/test_n1r_gate_apply.py','docs/records/labelfix/secondary/prompts/sep2.md')]
    products=[p for folder in ('n1r','n1e') for p in (BASE/folder).rglob('*') if p.is_file()]
    pack_files=[p for p in Path(build['pack_root']).rglob('*') if p.is_file()]
    outputs={str(p):sha(p) for p in sources+products+pack_files+[report,BASE/'N1R_TESTS.xml',BASE/'N1R_REGRESSION.xml']}
    result=dict(schema='N1R-v1',status='PREPARED_NOT_RELEASE_QUALIFIED',rule_hash=rule['rule_hash'],
        held_out=held,fit_metrics=fit_stats,locked=dict(build,closures=closures),tests=dict(targeted=targeted,regression=regression),
        gate_scorer_applier_tests_passed=fixtures,network=False,browser=False,computer_use=False,git_writes=False,
        reading_run=False,training_applier_run=False,lqb_registered=False,rule_changed_after_locked=False,
        blockers=['held-out raised precision undefined (zero predictions); recall 0/2',
                  '36 selected locked slots need exact localization or lead rulings',
                  'locked two-read truth not yet collected',
                  'six historical-pack regression tests fail on missing scratch images',
                  'v2 useful localization requires crop/label-bound geometry sidecar'],
        authority_documents={str(ROOT/p):sha(ROOT/p) for p in ('docs/records/labelfix/secondary/PLAN.md','docs/records/labelfix/secondary/N1T_LEAD_RAISED.md')},
        outputs=outputs,hash_policy='Frozen rule SHA is exact JSON bytes; outputs exclude this receipt; no real gate or training release claimed.')
    write(BASE/'N1R_RECEIPT.json',result)
    print(json.dumps(dict(status=result['status'],rule_hash=rule['rule_hash'],targeted=targeted['passed'],gate_applier=fixtures,
                          regression_passed=regression['passed'],regression_failed=len(regression['failed']),outputs=len(outputs))))
if __name__=='__main__':main()
